import 'package:flutter/material.dart';
import 'core/api.dart';import 'core/loading.dart';import 'core/push.dart';import 'core/ui.dart';import 'screens/login.dart';import 'screens/shell.dart';import 'screens/manager_shell.dart';import 'screens/admin_shell.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();runApp(const MleySoftApp());}
class MleySoftApp extends StatelessWidget{const MleySoftApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'MleySoft Aidat',theme:ThemeData(useMaterial3:true,fontFamily:'Roboto',scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:brand,brightness:Brightness.light,surface:Colors.white),appBarTheme:const AppBarTheme(backgroundColor:bg,surfaceTintColor:Colors.transparent,elevation:0),inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:Colors.white,contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:16),border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:const BorderSide(color:Color(0xFFEAECF0))),enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:const BorderSide(color:Color(0xFFEAECF0))),focusedBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:const BorderSide(color:ink,width:1.4))),filledButtonTheme:FilledButtonThemeData(style:FilledButton.styleFrom(backgroundColor:ink,foregroundColor:Colors.white,minimumSize:const Size(0,54),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18)),textStyle:const TextStyle(fontWeight:FontWeight.w800)))),home:const Boot());}
class Boot extends StatefulWidget{const Boot({super.key});@override State<Boot> createState()=>_BootState();}class _BootState extends State<Boot>{bool? ok;String? role;@override void initState(){super.initState();PushService.init(registerToken:false);check();}Future<void>check()async{final t=await Api.token();if(t==null||t.isEmpty){ok=false;if(mounted)setState((){});return;}role=await Api.role();try{final me=await Api.request('me');role=me['user']?['role']?.toString()??role; if(role!=null)await Api.saveRole(role!);ok=true;await PushService.init();}on ApiException catch(e){if(e.statusCode==401){await Api.clear();ok=false;}else if(role!=null){ok=true;}else{ok=false;}}catch(_){if(role!=null){ok=true;}else{ok=false;}}if(mounted)setState((){});}@override Widget build(BuildContext c){if(ok==null)return const Scaffold(backgroundColor:Colors.white,body:BrandLoader());if(!ok!)return const LoginScreen();if(role=='super_admin')return const AdminShell();if(role=='manager')return const ManagerShell();return const AppShell();}}
